SourceCode.Declaration:
internal class GUPRetailPeriodicDiscountFormEventHandler
{
    protected const RetailPricingPriorityNumber CalculationSequenceBasis = 1000;


}

Method.Source:
[FormDataSourceEventHandler(formDataSourceStr(RetailPeriodicDiscount, RetailPeriodicDiscount), FormDataSourceEventType::Written)]
public static void RetailPeriodicDiscount_OnWritten(FormDataSource sender, FormDataSourceEventArgs e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        RetailPeriodicDiscount retailPeriodicDiscount = sender.cursor();

        if (retailPeriodicDiscount.PriceComponentCodeName)
        {
            GUPPriceComponentCodeSetup      marginComponentSetup;
            RetailPricingPriorityTable      retailPricingPriorityTable;
            RetailPricingPriorityNumber     priorityNumber;

            select firstonly CalculationSequence from marginComponentSetup
                where marginComponentSetup.PriceComponentCodeName == retailPeriodicDiscount.PriceComponentCodeName;

            priorityNumber = marginComponentSetup.CalculationSequence > 0 ? CalculationSequenceBasis - marginComponentSetup.CalculationSequence : 0;

            select firstonly retailPricingPriorityTable where retailPricingPriorityTable.PriorityNumber == priorityNumber;
            if (!retailPricingPriorityTable)
            {
                retailPricingPriorityTable.PriorityNumber = priorityNumber;
                retailPricingPriorityTable.insert();
            }

            if (retailPeriodicDiscount.PricingPriorityNumber != priorityNumber)
            {
                retailPeriodicDiscount.selectForUpdate(true);
                retailPeriodicDiscount.PricingPriorityNumber = priorityNumber;
                retailPeriodicDiscount.doUpdate();
            }
        }
    }
}

[FormControlEventHandler(formControlStr(RetailPeriodicDiscount, Discount_discountType), FormControlEventType::Modified)]
public static void Discount_discountType_OnModified(FormControl sender, FormControlEventArgs e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        RetailPeriodicDiscount retailPeriodicDiscount = sender.dataSourceObject().cursor();
        if (retailPeriodicDiscount is RetailDiscountMultibuy)
        {
            RetailDiscountMultibuy multibuy = retailPeriodicDiscount as RetailDiscountMultibuy;
            FormRun formRun = sender.formRun();
            if (multibuy.MultibuyDiscountType != RetailDiscountTypeEnum::UnitPriceDiscAmt)
            {
                retailPeriodicDiscount.ShouldUseInterval = NoYes::No;
                formRun.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_RetailDiscountMultibuy_UseInterval)).enabled(false);
            }
            else
            {
                formRun.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_RetailDiscountMultibuy_UseInterval)).enabled(true);
            }
        }

    }
}
